uture deductions."}, {"id": "6e097636-4584-43e7-b365-1704fe474749", "type": "subtopic", "title": "Divisive transactions", "children": [{"id": "82e4b044-ec80-4f01-8994-9f8255601e2a", "type": "concept", "title": "Section 355"}, {"id": "0f21754e-9c44-4460-a893-25573523168d", "type": "concept", "title": "Active trade or business"}, {"id": "b731cf61-7921-4328-aad4-9511e3e4d8ef", "type": "concept", "title": "Device and business purpose tests"}], "description": "Spin-offs and split-offs require special nonrecognition rules."}]}, {"id": "9177d4d7-6caf-42a1-a578-a62a1186bf03", "type": "topic", "title": "International Corporate Tax: Inbound, Outbound, and Cross-Border Planning", "description": "This module introduces U.S. corporate international tax issues that affect multinational groups.", "children": [{"id": "deba9838-5535-4cef-8c6e-26513e1fd416", "type": "subtopic", "title": "Outbound rules", "children": [{"id": "ec8270e6-1430-403b-a95b-1f9dc21ad1a7", "type": "concept", "title": "Controlled foreign corporations"}, {"id": "88000e7b-c19a-40f6-abeb-160c120a90ee", "type": "concept", "title": "Subpart F"}, {"id": "b41320cc-35ef-4dfa-8b09-c407acde6aa8", "type": "concept", "title": "GILTI and foreign tax credits"}], "description": "U.S. corporations with foreign operations face anti-deferral and participation rules."}, {"id": "56edc108-cb8e-4f0f-a919-6afcf9be77e8", "type": "subtopic", "title": "Inbound rules", "children": [{"id": "113df16b-5bf0-417d-8979-899c286aaf8c", "type": "concept", "title": "Effectively connected income"}, {"id": "42389991-3d9c-4913-9a56-c5d0e204e7a9", "type": "concept", "title": "FDAP withholding"}, {"id": "f60b50f5-1f31-4f76-945d-ae8c9f4fa4f4", "type": "concept", "title": "Branch profits tax"}], "description": "Foreign corporations investing in the U.S. face source, withholding, and branch rules."}, {"id": "5e9045e6-4410-48da-9e32-0f9c27362dde", "type": "subtopic", "title": "Transfer pricing and treaties", "children": [{"id": "7af47769-0793-4817-bdbe-a67